const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const n = parseInt(tok[0]);
const g = tok.slice(1, 1 + n);
const cols = new Array(n).fill(false);
const d1 = new Array(2 * n).fill(false);
const d2 = new Array(2 * n).fill(false);
function go(r) {
  if (r === n) return 1;
  let total = 0;
  for (let c = 0; c < n; c++) {
    if (g[r][c] === '.' && !cols[c] && !d1[r - c + n] && !d2[r + c]) {
      cols[c] = d1[r - c + n] = d2[r + c] = true;
      total += go(r + 1);
      cols[c] = d1[r - c + n] = d2[r + c] = false;
    }
  }
  return total;
}
console.log(go(0));

