import java.util.*;

public class Main {
    static int n;
    static String[] g;
    static boolean[] cols, d1, d2;

    static int go(int r) {
        if (r == n) return 1;
        int total = 0;
        for (int c = 0; c < n; c++) {
            if (g[r].charAt(c) == '.' && !cols[c] && !d1[r - c + n] && !d2[r + c]) {
                cols[c] = d1[r - c + n] = d2[r + c] = true;
                total += go(r + 1);
                cols[c] = d1[r - c + n] = d2[r + c] = false;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        g = new String[n];
        for (int i = 0; i < n; i++) g[i] = sc.next();
        cols = new boolean[n];
        d1 = new boolean[2 * n + 1];
        d2 = new boolean[2 * n + 1];
        System.out.println(go(0));
    }
}

