#include <bits/stdc++.h>
using namespace std;
int n;
vector<string> g;
vector<char> cols, d1, d2;

int go(int r) {
    if (r == n) return 1;
    int total = 0;
    for (int c = 0; c < n; c++) {
        if (g[r][c] == '.' && !cols[c] && !d1[r - c + n] && !d2[r + c]) {
            cols[c] = d1[r - c + n] = d2[r + c] = 1;
            total += go(r + 1);
            cols[c] = d1[r - c + n] = d2[r + c] = 0;
        }
    }
    return total;
}

int main() {
    cin >> n;
    g.resize(n);
    for (auto &s : g) cin >> s;
    cols.assign(n + 1, 0);
    d1.assign(2 * n + 2, 0);
    d2.assign(2 * n + 2, 0);
    cout << go(0) << endl;
    return 0;
}
